## 5) Partial failures + retry logic

You already have retry logic: it retries `max_retries` times and returns the last error.

We can simulate “fail twice, succeed third time” using an atomic counter (again needs the injection point described above):

```rust
#[tokio::test]
async fn process_retries_and_eventually_succeeds() {
    let mut cfg = ProcessConfig::default();
    cfg.max_retries = 3;
    cfg.timeout = Duration::from_secs(1);

    let attempts = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
    let attempts2 = attempts.clone();

    let out = process_with_inner("hello world", &cfg, move |input| {
        let attempts2 = attempts2.clone();
        let input = input.to_string();
        async move {
            let n = attempts2.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            if n < 2 {
                Err(ProcessError::Unknown) // transient-ish failure
            } else {
                // delegate to real logic or return a fixed output
                Ok(ProcessedOutput {
                    original: input.clone(),
                    transformed: "HELLO WORLD".to_string(),
                    word_count: 2,
                    char_count: input.chars().count(),
                    processing_time_ms: 0,
                })
            }
        }
    })
    .await
    .unwrap();

    assert_eq!(attempts.load(std::sync::atomic::Ordering::SeqCst), 3);
    assert_eq!(out.transformed, "HELLO WORLD");
}
```

Also test “always fails => returns last error”:

```rust
#[tokio::test]
async fn process_returns_last_error_after_retries() {
    let mut cfg = ProcessConfig::default();
    cfg.max_retries = 3;
    cfg.timeout = Duration::from_secs(1);

    let err = process_with_inner("hello", &cfg, |_input| async {
        Err(ProcessError::Unknown)
    })
    .await
    .unwrap_err();

    assert!(matches!(err, ProcessError::Unknown));
}
```

